if (element.id === 'lightbox-style-injected') return;
element.id = 'lightbox-style-injected';

var style = document.createElement('style');
style.textContent =
  '.tutorial-lightbox-overlay { ' +
  '  position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; ' +
  '  background: rgba(0,0,0,0.85); z-index: 999999; ' +
  '  display: flex; align-items: center; justify-content: center; flex-direction: column; ' +
  '  cursor: zoom-out; opacity: 0; transition: opacity 0.25s ease; ' +
  '}' +
  '.tutorial-lightbox-overlay.tutorial-lightbox-visible { opacity: 1; }' +
  '.tutorial-lightbox-close { ' +
  '  position: fixed; top: 16px; right: 24px; z-index: 1000000; ' +
  '  background: rgba(255,255,255,0.9); border: none; border-radius: 50%; width: 44px; height: 44px; ' +
  '  font-size: 24px; cursor: pointer; display: flex; align-items: center; justify-content: center; ' +
  '  box-shadow: 0 2px 8px rgba(0,0,0,0.3); transition: transform 0.15s ease; ' +
  '}' +
  '.tutorial-lightbox-close:hover { transform: scale(1.1); }' +
  '.tutorial-lightbox-nav { ' +
  '  position: fixed; top: 50%; transform: translateY(-50%); z-index: 1000000; ' +
  '  background: rgba(255,255,255,0.85); border: none; border-radius: 50%; width: 48px; height: 48px; ' +
  '  font-size: 28px; cursor: pointer; display: flex; align-items: center; justify-content: center; ' +
  '  box-shadow: 0 2px 8px rgba(0,0,0,0.3); transition: transform 0.15s ease; color: #333; ' +
  '}' +
  '.tutorial-lightbox-nav:hover { transform: translateY(-50%) scale(1.1); }' +
  '.tutorial-lightbox-prev { left: 20px; }' +
  '.tutorial-lightbox-next { right: 20px; }' +
  '.tutorial-lightbox-image-wrap { ' +
  '  max-width: 90vw; max-height: 70vh; position: relative; display: flex; align-items: center; justify-content: center; ' +
  '}' +
  '.tutorial-lightbox-image { ' +
  '  max-width: 90vw; max-height: 65vh; object-fit: contain; border-radius: 8px; ' +
  '  box-shadow: 0 4px 24px rgba(0,0,0,0.5); cursor: default; ' +
  '}' +
  '.tutorial-lightbox-caption { ' +
  '  color: #fff; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; ' +
  '  font-size: 16px; max-width: 80vw; text-align: center; margin-top: 16px; padding: 0 20px; ' +
  '  line-height: 1.5; background: rgba(0,0,0,0.5); border-radius: 8px; padding: 12px 20px; ' +
  '}' +
  '.tutorial-lightbox-counter { ' +
  '  color: rgba(255,255,255,0.7); font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; ' +
  '  font-size: 13px; margin-top: 8px; ' +
  '}' +
  '.wikia-gallery-item .gallery-image-wrapper a.image.lightbox, ' +
  '.thumb.mw-halign-right a.mw-file-description.image, ' +
  '.thumb.mw-halign-center a.mw-file-description.image { ' +
  '  cursor: zoom-in !important; outline: 2px solid transparent; outline-offset: 4px; transition: outline-color 0.2s ease; ' +
  '}' +
  '.wikia-gallery-item .gallery-image-wrapper a.image.lightbox:hover, ' +
  '.thumb.mw-halign-right a.mw-file-description.image:hover, ' +
  '.thumb.mw-halign-center a.mw-file-description.image:hover { ' +
  '  outline-color: #FA005A !important; ' +
  '}' +
  '.gallery-icon-container.view-image { display: none !important; }' +
  '';

document.head.appendChild(style);

var overlay = null;
var currentImages = [];
var currentIndex = 0;

function collectTutorialImages() {
  var imgs = [];
  // Gallery items (main tutorial screenshots)
  var galleryItems = element.querySelectorAll('.wikia-gallery-item .gallery-image-wrapper a.image.lightbox');
  for (var i = 0; i < galleryItems.length; i++) {
    var link = galleryItems[i];
    var imgEl = link.querySelector('img.thumbimage');
    var captionEl = link.closest('.wikia-gallery-item').querySelector('.lightbox-caption');
    if (imgEl) {
      var hiResSrc = imgEl.getAttribute('data-src') || imgEl.src;
      // Get higher resolution by removing scale-to-width-down
      var fullSrc = hiResSrc.replace(/\/scale-to-width-down\/\d+/, '');
      imgs.push({
        thumb: imgEl,
        link: link,
        src: fullSrc,
        caption: captionEl ? captionEl.textContent.trim() : (imgEl.getAttribute('alt') || '')
      });
    }
  }
  // Standalone thumbnail figures
  var thumbs = element.querySelectorAll('.thumb.mw-halign-right a.mw-file-description.image, .thumb.mw-halign-center a.mw-file-description.image');
  for (var j = 0; j < thumbs.length; j++) {
    var tLink = thumbs[j];
    var tImg = tLink.querySelector('img.thumbimage');
    var figcaption = tLink.closest('.thumb').querySelector('.thumbcaption .caption');
    if (tImg) {
      var tHiRes = tImg.getAttribute('data-src') || tImg.src;
      var tFullSrc = tHiRes.replace(/\/scale-to-width-down\/\d+/, '');
      imgs.push({
        thumb: tImg,
        link: tLink,
        src: tFullSrc,
        caption: figcaption ? figcaption.textContent.trim() : (tImg.getAttribute('alt') || '')
      });
    }
  }
  return imgs;
}

function openLightbox(index) {
  currentImages = collectTutorialImages();
  if (currentImages.length === 0) return;
  currentIndex = index;
  showImage(currentIndex);
}

function showImage(index) {
  if (index < 0 || index >= currentImages.length) return;
  currentIndex = index;

  if (!overlay) {
    overlay = document.createElement('div');
    overlay.className = 'tutorial-lightbox-overlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', 'Tutorial screenshot viewer');

    var closeBtn = document.createElement('button');
    closeBtn.className = 'tutorial-lightbox-close';
    closeBtn.innerHTML = '&#10005;';
    closeBtn.setAttribute('aria-label', 'Close lightbox');
    closeBtn.addEventListener('click', function(e) { e.stopPropagation(); closeLightbox(); });

    var prevBtn = document.createElement('button');
    prevBtn.className = 'tutorial-lightbox-nav tutorial-lightbox-prev';
    prevBtn.innerHTML = '&#8249;';
    prevBtn.setAttribute('aria-label', 'Previous screenshot');
    prevBtn.addEventListener('click', function(e) { e.stopPropagation(); showImage(currentIndex - 1); });

    var nextBtn = document.createElement('button');
    nextBtn.className = 'tutorial-lightbox-nav tutorial-lightbox-next';
    nextBtn.innerHTML = '&#8250;';
    nextBtn.setAttribute('aria-label', 'Next screenshot');
    nextBtn.addEventListener('click', function(e) { e.stopPropagation(); showImage(currentIndex + 1); });

    var imgWrap = document.createElement('div');
    imgWrap.className = 'tutorial-lightbox-image-wrap';

    overlay.appendChild(closeBtn);
    overlay.appendChild(prevBtn);
    overlay.appendChild(nextBtn);
    overlay.appendChild(imgWrap);

    overlay.addEventListener('click', function(e) {
      if (e.target === overlay) closeLightbox();
    });

    document.body.appendChild(overlay);
  }

  var imgWrap = overlay.querySelector('.tutorial-lightbox-image-wrap');
  imgWrap.innerHTML = '';

  var img = new Image();
  img.className = 'tutorial-lightbox-image';
  img.src = currentImages[currentIndex].src;
  img.alt = currentImages[currentIndex].caption;
  imgWrap.appendChild(img);

  if (currentImages[currentIndex].caption) {
    var captionDiv = document.createElement('div');
    captionDiv.className = 'tutorial-lightbox-caption';
    captionDiv.textContent = currentImages[currentIndex].caption;
    overlay.appendChild(captionDiv);
  }

  if (currentImages.length > 1) {
    var counter = document.createElement('div');
    counter.className = 'tutorial-lightbox-counter';
    counter.textContent = (currentIndex + 1) + ' / ' + currentImages.length;
    overlay.appendChild(counter);
  }

  requestAnimationFrame(function() {
    overlay.classList.add('tutorial-lightbox-visible');
  });
}

function closeLightbox() {
  if (!overlay) return;
  overlay.classList.remove('tutorial-lightbox-visible');
  setTimeout(function() {
    if (overlay && overlay.parentNode) {
      overlay.parentNode.removeChild(overlay);
    }
    overlay = null;
  }, 250);
}

// Attach click handlers to all tutorial screenshot links
var galleryLinks = element.querySelectorAll('.wikia-gallery-item .gallery-image-wrapper a.image.lightbox');
for (var g = 0; g < galleryLinks.length; g++) {
  (function(link, idx) {
    link.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      openLightbox(idx);
    });
  })(galleryLinks[g], g);
}

// Attach click handlers to standalone thumb figures
var thumbLinks = element.querySelectorAll('.thumb.mw-halign-right a.mw-file-description.image, .thumb.mw-halign-center a.mw-file-description.image');
for (var t = 0; t < thumbLinks.length; t++) {
  (function(link, idx) {
    var galleryCount = collectTutorialImages().length - thumbLinks.length;
    link.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      openLightbox(galleryCount + idx);
    });
  })(thumbLinks[t], t);
}

// Keyboard navigation
document.addEventListener('keydown', function(e) {
  if (!overlay || !overlay.classList.contains('tutorial-lightbox-visible')) return;
  if (e.key === 'Escape') closeLightbox();
  if (e.key === 'ArrowLeft' && currentImages.length > 1) showImage(currentIndex - 1);
  if (e.key === 'ArrowRight' && currentImages.length > 1) showImage(currentIndex + 1);
});
